import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash) public {
        // Give the contract 1 ether, then fund msg.sender with 1 ether to lock in a guess
        vm.deal(address(this), 1 ether);
        vm.deal(address(c), 1 ether); // already has 1 from constructor, but ensure exactly 1 for clarity
        // Reset for clean state: send 1 ether to c
