import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        vm.deal(address(this), 1 ether);
        c = new C(); 
    }
    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        // Ensure blockOffset > 1 so we can test the difference
        vm.assume(blockOffset > 1);
        vm.deal(address(this), 1 ether);
        // First, lock in a guess
        c.lockInGuess{value: 1 ether}(hash);

        // Record the block when lockInGuess was called
        uint256 recordedBlock = block.number + 1;

        // Now warp to a block where settle() can be called
        // For P: require block.number > recordedBlock
        // For M: require block.number >= recordedBlock
        // We want to test the case where block.number == recordedBlock to expose the difference
        vm.warp(block.timestamp + 1);

        // Make the call to settle()
        bool reverted;
        if (block.number == recordedBlock) {
            // In P, this should revert; in M, it may not
            (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));
            reverted = !success;
        } else {
            // Otherwise both should behave the same (not revert if guess is wrong)
            // But we only care about the property when block.number == recordedBlock
            // For simplicity, skip other cases
            return;
        }

        // General rule: when block.number == recordedBlock, settle() should revert
        assertTrue(reverted);
    }
}

