pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Ensure the contract has at least 2 ether for the reward
        vm.deal(address(c), 2 ether);

        // Fund a user with 1 ether to lock in a guess
        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance block number to make settlement possible
        vm.roll(block.number + 2);

        // Record balances before settlement
        uint balanceBefore = address(c).balance;
        uint userBalanceBefore = user.balance;

        // Attempt settlement
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("settle()"));

        // Only consider cases where settlement succeeded (i.e., the guess could be correct)
        // In the reference, correct guess gives exactly 2 ether, so total balance sum increases by 0
        // The buggy version gives address(this).balance, so total balance sum increases differently
        if (success) {
            uint balanceAfter = address(c).balance;
            uint userBalanceAfter = user.balance;
            // General rule: The sum of (contract balance + user balance) is conserved plus the fixed reward
            // For reference: user gains 2 ether, contract loses 2 ether, sum unchanged
            // For buggy: user gains all contract balance, contract becomes 0, sum changes
            // So the invariant is: userBalanceAfter + balanceAfter == userBalanceBefore + balanceBefore - 2 ether
            // Actually, in reference: user gets 2 ether, contract loses 2 ether, so sum is same
            // But in bug: user gets all contract balance, so sum after = userBalanceBefore + balanceBefore - 2 ether (the initial 2 ether requirement? No, require doesn't spend)
            // Let's derive: reference sends exactly 2 ether. So userBalanceAfter = userBalanceBefore + 2, balanceAfter = balanceBefore - 2. Sum = userBalanceBefore + balanceBefore.
            // Buggy sends address(this).balance = balanceBefore. So userBalanceAfter = userBalanceBefore + balanceBefore, balanceAfter = 0. Sum = userBalanceBefore + balanceBefore.
            // Wait, both have same sum? No, require(address(this).balance >= 2 ether) is checked, but the transfer amount differs.
            // Actually both sums are equal: userBalanceAfter + balanceAfter = userBalanceBefore + balanceBefore because the transfer just moves ether.
            // So this property doesn't distinguish. Need a different invariant.
            // Let's use: userBalanceAfter - userBalanceBefore == 2 ether for reference, but buggy gives balanceBefore.
            // So rule: user balance increase equals 2 ether.
            assertTrue(user.balance - userBalanceBefore == 2 ether);
        }
    }
}

