import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, bytes32 actualGuess) public {
        // Ensure actualGuess is a valid guess (any bytes32 is valid)
        vm.assume(actualGuess != bytes32(0)); // avoid edge case where guess accidentally matches
        // Fund the contract with 2 ether so settle can pay out
        vm.deal(address(c), 2 ether);
        // Fund caller with 1 ether to pay lockInGuess
        vm.deal(address(this), 1 ether);
        // Call lockInGuess with the hash of the actualGuess (simulating the intended guess)
        bytes32 hash = keccak256(abi.encodePacked(actualGuess));
        c.lockInGuess{value: 1 ether}(hash);
        // Now we need to settle after the block has advanced past the locked-in block
        vm.roll(block.number + 2); // advance to next block
        // The settled guess is actualGuess, so if the contract checks equality it pays; if inequality it reverts
        // The reference (correct) version: if guess == answer, transfer 2 ether, else do nothing and settle returns normally.
        // Our general rule: after lockInGuess with a valid hash, settling should never revert (it either pays or does nothing).
        // The buggy version reverts when guess == answer because it requires !=, so it cannot pay out and may revert if balance insufficient.
        // We'll check that the call does not revert.
        bool didRevert;
        (didRevert, ) = address(c).call(abi.encodeWithSignature("settle()"));
        assertTrue(!didRevert, "Settle should not revert");
    }
}

