        }

        uint256 balanceAfter = address(this).balance;

        // General rule: If settle succeeded, the balance change is exactly 2 ether
        // In the correct version, this happens only when guess == answer.
        // In the buggy version, this happens when guess != answer.
        // We cannot directly check the guess vs answer because answer is unknown.
        // But the rule holds that the balance increase (2 ether) occurs if and only if settle didn't revert.
        if (settled) {
            assertTrue(balanceAfter - balanceBefore == 2 ether);
        } else {
            assertTrue(balanceAfter - balanceBefore == 0);
        }
    }
}

