pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Fund the contract with 1 ether for the call and additional 2 ether for potential reward
        vm.deal(address(c), 3 ether);
        // Fund the caller
        address caller = address(this);
        vm.deal(caller, 1 ether);
        // Call lockInGuess with exactly 1 ether
        vm.deal(caller, 1 ether);
        c.lockInGuess{value: 1 ether}(guess);
        // Warp to a block after the target block (guesses[caller].block = block.number + 1 at lockInGuess)
        vm.roll(block.number + 2);
        // Attempt to settle; should only succeed if guess equals the block hash
        bool success;
        bytes memory data = abi.encodeWithSignature("settle()");
        (success, ) = address(c).call(data);
        // Compute the answer = keccak256(abi.encodePacked(blockhash(block.number - 1)))
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        // General rule: settle() should revert when guess != answer, succeed otherwise
        assertTrue((guess == answer) == success, "settle() must only succeed when guess matches answer");
    }
}
